python3 - <<'EOF'
import re
from datetime import datetime

with open('team_meeting_2026-08-19.ics') as f:
    content = f.read()

errors = []

# 1. Balanced BEGIN/END blocks
for block in ['VCALENDAR', 'VEVENT', 'VTIMEZONE', 'VALARM', 'STANDARD']:
    b = content.count(f'BEGIN:{block}')
    e = content.count(f'END:{block}')
    if b != e:
        errors.append(f'Unbalanced {block}: {b} BEGIN vs {e} END')

# 2. Required fields
for field in ['VERSION:2.0', 'PRODID', 'UID:', 'DTSTAMP:', 'DTSTART', 'DTEND', 'SUMMARY:Team Meeting']:
    if field not in content:
        errors.append(f'Missing required field: {field}')

# 3. Check DTEND > DTSTART
dtstart = re.search(r'DTSTART;TZID=Asia/Shanghai:(\d{8}T\d{6})', content).group(1)
dtend = re.search(r'DTEND;TZID=Asia/Shanghai:(\d{8}T\d{6})', content).group(1)
start = datetime.strptime(dtstart, '%Y%m%dT%H%M%S')
end = datetime.strptime(dtend, '%Y%m%dT%H%M%S')
if end <= start:
    errors.append('DTEND must be after DTSTART')
else:
    print(f'Duration: {end - start} (expected 1 hour)')
print(f'Event: {dtstart} -> {dtend} (Asia/Shanghai)')

# 4. Check date is a Wednesday
if start.strftime('%A') != 'Wednesday':
    errors.append(f'Expected Wednesday, got {start.strftime("%A")}')

if errors:
    print('VALIDATION ERRORS:')
    for e in errors:
        print(f'  - {e}')
else:
    print('VALIDATION PASSED: File is valid and correct.')
EOF
